298	fn assert_native_rejection_behavior(
299	    fixture: &Fixture,
300	    grant: &Path,
301	    directory: &Path,
302	    existing: &Path,
303	    new_target: &Path,
304	    policy: &AccessPolicy,
305	    directory_created: bool,
306	) {
307	    let existing_bytes = existing.as_os_str().as_bytes();
308	    assert!(existing_bytes.contains(&0xff));
309	    assert!(existing_bytes.contains(&0xfe));
310	    assert!(new_target.as_os_str().as_bytes().contains(&0xfd));
311	    assert!(!existing_bytes.contains(&0));
312	    assert_native_path_rejection(existing);
313	    assert_native_path_rejection(new_target);
314	    if directory_created {
315	        assert_eq!(
316	            policy.resolve_granted_directory(directory).unwrap(),
317	            fs::canonicalize(directory).unwrap()
318	        );
319	    } else {
320	        assert_native_path_rejection(directory);
321	        assert_eq!(policy.resolve_granted_directory(directory), Err(AccessError::NotFound));
322	    }
323	
324	    // A valid UTF-8 path formed by lossy replacement is deliberately present.
325	    // Raw inputs must be denied by the native filesystem result, never rewritten
326	    // to this different existing file.
327	    let lossy_existing = PathBuf::from(String::from_utf8_lossy(existing_bytes).into_owned());
328	    let lossy_directory = lossy_existing.parent().unwrap();
329	    fs::create_dir_all(lossy_directory).unwrap();
330	    fs::write(&lossy_existing, b"lossy replacement fixture").unwrap();
331	    let lossy_new_target = lossy_directory.join("new-�.svg");
332	
333	    assert_eq!(policy.resolve_existing(existing), Err(AccessError::NotFound));
334	    assert!(!policy.path_allowed(existing));
335	    assert_save_resolution_matches_native_lookup(policy, existing, directory);
336	    assert_save_resolution_matches_native_lookup(policy, new_target, directory);
337	
338	    assert_eq!(policy.resolve_existing(&lossy_existing).unwrap(), fs::canonicalize(&lossy_existing).unwrap());
339	    assert!(policy.path_allowed(&lossy_existing));
340	    assert_eq!(
341	        policy.resolve_save_path(&lossy_new_target).unwrap(),
342	        fs::canonicalize(lossy_directory).unwrap().join("new-�.svg")
343	    );
344	    assert_eq!(policy.resolve_granted_directory(lossy_directory).unwrap(), fs::canonicalize(lossy_directory).unwrap());
345	
346	    let mut nul_bytes = existing_bytes.to_vec();
347	    nul_bytes.push(0);
348	    let nul_path = OsString::from_vec(nul_bytes);
349	    assert_eq!(policy.resolve_existing(&nul_path), Err(AccessError::InvalidPath));
350	    assert!(!policy.path_allowed(&nul_path));
351	    assert_eq!(policy.resolve_save_path(&nul_path), Err(AccessError::InvalidPath));
352	    assert_eq!(policy.resolve_granted_directory(&nul_path), Err(AccessError::InvalidPath));
353	
354	    assert_outside_grant_rules(fixture, policy);
355	    assert_outside_raw_rejection(fixture, policy);
356	    assert!(directory.starts_with(grant));
357	}
