  2	//! Filesystem access grants used by the MCP document and save operations.
  3	//!
  4	//! The policy owns the environment inputs so callers and tests do not need to
  5	//! mutate process-global environment variables. Filesystem checks follow the
  6	//! same canonicalize/stat sequence as the C implementation; concurrent path
  7	//! replacement can therefore race these checks and later file operations.
  8	
  9	use std::ffi::{OsStr, OsString};
 10	use std::fs::{self, File};
 11	use std::io::{BufReader, Read};
 12	use std::os::unix::ffi::{OsStrExt, OsStringExt};
 13	use std::os::unix::fs::MetadataExt;
 14	use std::path::{Path, PathBuf};
 15	
 16	/// Largest accepted input and canonical output path, including the C NUL cap.
 17	pub const PATH_CAP: usize = 1024;
 18	/// Largest accepted `VEXEL_MCP_ALLOWED_DIRS` value, including the C NUL cap.
 19	pub const ALLOWED_DIRS_CAP: usize = 8192;
 20	const CONFIG_LINE_CAP: usize = PATH_CAP - 1;
 21	const CONFIG_LINE_LIMIT: usize = 128;
 22	const CONFIG_SUFFIX: &[u8] = b"/.config/vexel/mcp-allowed-dirs.txt";
 23	
 24	/// Why a requested path could not be resolved under the access contract.
 25	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
 26	pub enum AccessError {
 27	    /// Input is empty, contains an interior NUL, or exceeds the fixed cap.
 28	    InvalidPath,
 29	    /// The path does not exist or could not be canonicalized.
 30	    NotFound,
 31	    /// Existing targets must be regular files.
 32	    NotRegularFile,
 33	    /// A grant target or save parent must be a directory.
 34	    NotDirectory,
 35	    /// The canonical path is outside every configured grant.
 36	    NotGranted,
 37	}
 38	
 39	/// Owned access inputs. `allowed_dirs` and `home` are snapshots, not live
 40	/// references to process environment state.
 41	#[derive(Clone, Debug)]
 42	pub struct AccessPolicy {
 43	    allowed_dirs: Option<OsString>,
 44	    home: Option<PathBuf>,
 45	    current_uid: u32,
 46	}
 47	
 48	impl AccessPolicy {
 49	    /// Create an explicit policy, primarily for deterministic application
 50	    /// composition and tests. The real uid is captured from the accepted
 51	    /// native macOS identity interface.
 52	    pub fn new(allowed_dirs: Option<OsString>, home: Option<PathBuf>) -> Self {
 53	        Self {
 54	            allowed_dirs,
 55	            home,
 56	            current_uid: vexel_platform_macos::current_uid(),
 57	        }
 58	    }
 59	
 60	    /// Snapshot `VEXEL_MCP_ALLOWED_DIRS` and `HOME` from the current process.
 61	    pub fn from_environment() -> Self {
 62	        Self::new(
 63	            std::env::var_os("VEXEL_MCP_ALLOWED_DIRS"),
 64	            std::env::var_os("HOME").map(PathBuf::from),
 65	        )
 66	    }
 67	
 68	    /// Resolve an existing regular file to its canonical absolute path.
 69	    /// Inputs are raw macOS path bytes; `&str` and other `AsRef<OsStr>` values
 70	    /// are accepted without conversion through UTF-8.
 71	    pub fn resolve_existing(&self, path: impl AsRef<OsStr>) -> Result<PathBuf, AccessError> {
 72	        let path = path.as_ref();
 73	        validate_input(path)?;
 74	        let canonical = fs::canonicalize(path).map_err(|_| AccessError::NotFound)?;
 75	        ensure_output_bound(&canonical)?;
 76	        let metadata = fs::metadata(&canonical).map_err(|_| AccessError::NotFound)?;
 77	        if !metadata.is_file() {
 78	            return Err(AccessError::NotRegularFile);
 79	        }
 80	        Ok(canonical)
 81	    }
 82	
 83	    /// Return whether an existing regular file is inside a configured grant.
 84	    pub fn path_allowed(&self, path: impl AsRef<OsStr>) -> bool {
 85	        let path = path.as_ref();
 86	        let Ok(canonical) = self.resolve_existing(path) else {
 87	            return false;
 88	        };
 89	        self.is_granted(&canonical)
 90	    }
 91	
 92	    /// Resolve an existing regular file or a new leaf in an existing,
 93	    /// canonical directory, requiring a grant in either case.
 94	    pub fn resolve_save_path(&self, path: impl AsRef<OsStr>) -> Result<PathBuf, AccessError> {
 95	        let path = path.as_ref();
 96	        validate_input(path)?;
 97	        let requested = Path::new(path);
 98	        match fs::symlink_metadata(requested) {
 99	            Ok(_) => {
100	                let canonical = self.resolve_existing(path)?;
101	                if !self.is_granted(&canonical) {
102	                    return Err(AccessError::NotGranted);
103	                }
104	                Ok(canonical)
105	            }
106	            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
107	                self.resolve_new_save_path(path)
108	            }
109	            Err(_) => Err(AccessError::NotFound),
110	        }
111	    }
112	
113	    /// Resolve a granted directory to its canonical absolute path.
114	    pub fn resolve_granted_directory(
115	        &self,
116	        path: impl AsRef<OsStr>,
117	    ) -> Result<PathBuf, AccessError> {
118	        let path = path.as_ref();
119	        validate_input(path)?;
120	        let canonical = fs::canonicalize(path).map_err(|_| AccessError::NotFound)?;
121	        ensure_output_bound(&canonical)?;
122	        let metadata = fs::metadata(&canonical).map_err(|_| AccessError::NotFound)?;
123	        if !metadata.is_dir() {
124	            return Err(AccessError::NotDirectory);
125	        }
126	        if !self.is_granted(&canonical) {
127	            return Err(AccessError::NotGranted);
128	        }
129	        Ok(canonical)
130	    }
131	
132	    fn is_granted(&self, path: &Path) -> bool {
133	        self.granted_by_environment(path) || self.granted_by_config(path)
134	    }
135	
136	    fn granted_by_environment(&self, path: &Path) -> bool {
137	        let Some(value) = self.allowed_dirs.as_ref() else {
138	            return false;
139	        };
140	        let bytes = value.as_bytes();
141	        if bytes.is_empty() || bytes.len() >= ALLOWED_DIRS_CAP {
142	            return false;
143	        }
144	        let mut start = 0;
145	        while start < bytes.len() {
146	            let end = bytes[start..]
147	                .iter()
148	                .position(|byte| *byte == b':')
149	                .map_or(bytes.len(), |offset| start + offset);
150	            let item = &bytes[start..end];
151	            if !item.is_empty() && item.len() < PATH_CAP {
152	                let candidate = PathBuf::from(OsString::from_vec(item.to_vec()));
153	                if canonical_directory(&candidate)
154	                    .is_ok_and(|directory| path_is_inside(&directory, path))
155	                {
156	                    return true;
157	                }
158	            }
159	            start = end.saturating_add(1);
160	        }
161	        false
162	    }
163	
164	    fn granted_by_config(&self, path: &Path) -> bool {
165	        let Some(home) = self.home.as_ref() else {
166	            return false;
167	        };
168	        let home_bytes = home.as_os_str().as_bytes();
169	        if home_bytes.first() != Some(&b'/')
170	            || home_bytes.is_empty()
171	            || home_bytes.len().checked_add(CONFIG_SUFFIX.len() + 1).is_none_or(|n| n > PATH_CAP)
172	        {
173	            return false;
174	        }
175	        let mut config_bytes = Vec::with_capacity(home_bytes.len() + CONFIG_SUFFIX.len());
176	        config_bytes.extend_from_slice(home_bytes);
