258	fn config_grants<R: Read>(mut reader: BufReader<R>, path: &Path) -> bool {
259	    let mut line = [0_u8; CONFIG_LINE_CAP];
260	    let mut lines = 0;
261	    while lines < CONFIG_LINE_LIMIT {
262	        let mut length = 0;
263	        let mut complete = false;
264	        while length < line.len() {
265	            let mut byte = [0_u8; 1];
266	            match reader.read(&mut byte) {
267	                Ok(0) => {
268	                    complete = true;
269	                    break;
270	                }
271	                Ok(_) => {
272	                    line[length] = byte[0];
273	                    length += 1;
274	                    if byte[0] == b'\n' {
275	                        complete = true;
276	                        break;
277	                    }
278	                }
279	                Err(_) => return false,
280	            }
281	        }
282	        if length == 0 {
283	            break;
284	        }
285	        lines += 1;
286	        if length == CONFIG_LINE_CAP && !complete {
287	            continue;
288	        }
289	        let line_bytes = &line[..length];
290	        let nul = line_bytes.iter().position(|byte| *byte == 0).unwrap_or(length);
291	        let mut end = nul;
292	        while end > 0 && is_ascii_space(line[end - 1]) {
293	            end -= 1;
294	        }
295	        let mut start = 0;
296	        while start < end && is_ascii_space(line[start]) {
297	            start += 1;
298	        }
299	        if start == end || line[start] == b'#' {
300	            continue;
301	        }
302	        let candidate = PathBuf::from(OsString::from_vec(line[start..end].to_vec()));
303	        if canonical_directory(&candidate).is_ok_and(|directory| path_is_inside(&directory, path)) {
